insert into public.question_bank (id, category, prompt, options) values
(1,'ไลฟ์สไตล์','วันหยุดยาวในฝัน คุณอยากทำอะไรมากที่สุด?','["เที่ยวทะเล","เที่ยวภูเขาหรือธรรมชาติ","ท่องเมือง กิน ช้อป","นอนพักอยู่บ้าน"]'),
(2,'ความรัก','เดตแบบไหนที่คุณชอบที่สุด?','["ดูหนังแล้วทานข้าว","ทำอาหารด้วยกันที่บ้าน","ผจญภัยกลางแจ้ง","นั่งคาเฟ่เดินเล่น"]'),
(3,'ไลฟ์สไตล์','คุณเป็นคนตื่นเช้าหรือนอนดึก?','["ตื่นเช้ามาก","ตื่นสายหน่อย","นอนดึกเป็นประจำ","ขึ้นอยู่กับวัน"]'),
(4,'ความสัมพันธ์','เมื่อมีเรื่องไม่เข้าใจกัน คุณมักทำอย่างไร?','["คุยกันทันที","ขอเวลาสงบก่อนแล้วค่อยคุย","เขียนข้อความอธิบาย","รอให้อีกฝ่ายเริ่มคุย"]'),
(5,'ความรัก','ของขวัญแบบไหนที่คุณประทับใจที่สุด?','["ของที่ทำเอง","ของที่ใช้ได้จริง","ประสบการณ์ที่ได้ไปด้วยกัน","การ์ดหรือจดหมายจากใจ"]'),
(6,'ไลฟ์สไตล์','ช่วงเย็นหลังเลิกงาน คุณอยากทำอะไร?','["ออกกำลังกาย","เล่นเกมหรือดูซีรีส์","อ่านหนังสือหรือทำงานอดิเรก","พบปะเพื่อน"]'),
(7,'ไลฟ์สไตล์','อาหารมื้อโปรดของคุณคือแบบไหน?','["อาหารไทย","อาหารญี่ปุ่นหรือเกาหลี","ฟาสต์ฟู้ดหรือปิ้งย่าง","ขนมและของหวาน"]'),
(8,'ความรัก','คุณแสดงความรักด้วยวิธีใดมากที่สุด?','["คำพูดหวาน ๆ","การกอดหรือสัมผัส","การช่วยเหลือและดูแล","การให้เวลาคุณภาพ"]'),
(9,'อนาคต','คุณมองการเก็บเงินและใช้จ่ายอย่างไร?','["เก็บก่อนใช้","ใช้กับสิ่งที่ทำให้มีความสุข","วางแผนงบทุกเดือน","ใช้ตามสถานการณ์"]'),
(10,'อนาคต','อีก 5 ปีข้างหน้า คุณอยากอยู่ที่ไหน?','["เมืองใหญ่","ต่างจังหวัดที่สงบ","ต่างประเทศ","ที่ไหนก็ได้ที่มีความสุข"]'),
(11,'ไลฟ์สไตล์','สัตว์เลี้ยงในฝันของคุณคือ?','["สุนัข","แมว","สัตว์เลี้ยงตัวเล็กอื่น ๆ","ไม่เลี้ยงสัตว์"]'),
(12,'ความสัมพันธ์','เวลาเครียด คุณต้องการอะไรมากที่สุด?','["มีคนรับฟัง","อยู่คนเดียวสักพัก","ทำกิจกรรมเบนความสนใจ","กำลังใจสั้น ๆ"]'),
(13,'ไลฟ์สไตล์','คุณชอบเที่ยวแบบไหน?','["วางแผนทุกอย่างล่วงหน้า","วางแผนหลวม ๆ","ไปสบาย ๆ ไม่มีแผน","ซื้อทัวร์หรือแพ็กเกจ"]'),
(14,'ความสัมพันธ์','สิ่งที่สำคัญที่สุดในความสัมพันธ์สำหรับคุณคือ?','["ความซื่อสัตย์","การสื่อสาร","ความเคารพ","ความสนุกร่วมกัน"]'),
(15,'ไลฟ์สไตล์','คุณชอบฟังเพลงแนวไหน?','["ป็อป","ฮิปฮอปหรืออาร์แอนด์บี","ร็อกหรืออินดี้","ลูกทุ่งหรือลูกกรุง"]'),
(16,'ความรัก','วันเกิดของคุณ อยากฉลองแบบไหน?','["ปาร์ตี้ใหญ่","ทานข้าวกับคนสนิท","เซอร์ไพรส์เล็ก ๆ","ไม่ต้องจัดอะไร"]'),
(17,'ความสัมพันธ์','คุณอยากคุยกับคนรักบ่อยแค่ไหน?','["ตลอดทั้งวัน","เช้าและเย็น","ว่างเมื่อไรค่อยคุย","ไม่บ่อยแต่คุยแล้วมีคุณภาพ"]'),
(18,'อนาคต','คุณจัดการงานบ้านอย่างไร?','["ทำทันทีที่เห็น","ทำตามตาราง","แบ่งกันทำ","ทำเมื่อสะดวก"]'),
(19,'ไลฟ์สไตล์','หนังหรือซีรีส์แนวไหนที่คุณดูได้ไม่เบื่อ?','["โรแมนติกคอเมดี","แอ็กชันหรือไซไฟ","สยองขวัญหรือระทึกขวัญ","สารคดีหรือดราม่า"]'),
(20,'ไลฟ์สไตล์','ช่วงเวลาไหนของวันที่คุณมีความสุขที่สุด?','["ตอนเช้า","ตอนบ่าย","ตอนเย็น","ตอนดึก"]')
